import type {
  GeometryAccuracy,
  LineCursor,
  ParagraphHitTestResult,
  ParagraphLine,
  ParagraphLineStep,
  ParagraphLineWidthResolver,
  ParagraphMeasureOptions,
  ParagraphMetrics,
  ParagraphRangeRect,
  Point,
  PreparedParagraph,
  SyncTextGeometryBackend,
  TextGeometryBackendCapabilities,
  TextRange,
} from '../geometry-api.ts';
import {
  PARAGRAPH_OFFSET_UNIT,
  TEXT_GEOMETRY_API_STABILITY,
} from '../geometry-api.ts';
import type {
  ParagraphDirection,
  ParagraphFontStyle,
  ParagraphFontWeight,
  ParagraphRangeAnnotation,
  ParagraphSpec,
  ParagraphTextStyle,
  ParagraphTruncation,
} from '../paragraph-spec.ts';
import { BoundedLruMap } from '../internal/bounded-cache.ts';
import { createFullParagraphKey, createParagraphKey } from '../internal/paragraph-key.ts';

// Bounds the module-lifetime prepared-paragraph cache (see BoundedLruMap) —
// large enough that typical scroll/chat surfaces stay entirely cache-hit,
// small enough to cap memory for long-lived sessions.
const DEFAULT_PARAGRAPH_CACHE_LIMIT = 2000;

declare const appleTextLineCursorBrand: unique symbol;

type AppleHostCall = (operation: string, argsJson: string) => unknown;

type AppleHostWidthMode = 'definite' | 'min-content' | 'max-content';

type ApplePreparedCursor = {
  readonly [appleTextLineCursorBrand]: true;
  readonly lineIndex: number;
};

interface AppleHostTextStyle {
  readonly fontFamilies: readonly string[];
  readonly fontSize: number;
  readonly fontWeight: number;
  readonly fontStyle: ParagraphFontStyle;
  readonly fontVariantNumeric?: string;
  readonly lineHeight?: number;
  readonly letterSpacing?: number;
  readonly locale?: string;
}

interface AppleHostTextSpan {
  text: string;
  readonly style: AppleHostTextStyle;
}

interface AppleHostParagraphPayload {
  readonly key: string;
  readonly spans: readonly AppleHostTextSpan[];
  readonly baseDirection?: ParagraphDirection;
  readonly maxLines?: number;
  readonly truncation?: ParagraphTruncation;
}

interface AppleHostMeasureRequest {
  readonly paragraph: AppleHostParagraphPayload;
  readonly widthMode: AppleHostWidthMode;
  readonly maxWidth?: number;
}

interface AppleHostPoint {
  readonly x: number;
  readonly y: number;
}

interface AppleHostLine {
  readonly index: number;
  readonly start: number;
  readonly end: number;
  readonly width: number;
  readonly height: number;
  readonly baseline: number;
  readonly origin: AppleHostPoint;
}

interface AppleHostLayoutRequest {
  readonly paragraph: AppleHostParagraphPayload;
  readonly maxWidth: number;
}

interface AppleHostLayoutResponse {
  readonly lines: readonly AppleHostLine[];
}

type AppleHostParagraphMetrics = Omit<
  ParagraphMetrics,
  'geometryAccuracy' | 'offsetUnit'
>;

const DEFAULT_FONT_SIZE = 16;
const DEFAULT_FONT_WEIGHT = 400;
const DEFAULT_FONT_STYLE: ParagraphFontStyle = 'normal';
const DEFAULT_MIN_CONTENT_WIDTH = 1;
const APPLE_GEOMETRY_ACCURACY = 'approximate' satisfies GeometryAccuracy;

export const appleTextGeometryCapabilities = {
  apiStability: TEXT_GEOMETRY_API_STABILITY,
  backendId: 'apple-host',
  offsetUnit: PARAGRAPH_OFFSET_UNIT,
  geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
  attachments: {
    support: 'unsupported',
    canonicalOffsetCharacter: 'U+FFFC',
    canonicalUtf16CodeUnits: 1,
  },
  paragraphSpec: {
    textSpans: 'supported',
    rangeAnnotations: 'supported',
    locale: 'supported',
    baseDirection: 'supported',
    writingMode: 'default-only',
    textAlign: 'default-only',
    lineBreak: 'default-only',
    overflowWrap: 'default-only',
    maxLines: 'supported',
    truncation: 'supported',
  },
  textStyle: {
    color: 'geometry-neutral',
    fontFamily: 'supported',
    fontSize: 'supported',
    fontWeight: 'supported',
    fontStyle: 'supported',
    fontVariantNumeric: 'supported',
    fontFeatureSettings: 'unsupported',
    fontVariationSettings: 'unsupported',
    textAlign: 'default-only',
    writingMode: 'default-only',
    lineHeight: 'supported',
    letterSpacing: 'supported',
    textDecorationLine: 'geometry-neutral',
    locale: 'supported',
  },
  queries: {
    measure: 'supported',
    minContentWidth: 'supported',
    maxContentWidth: 'supported',
    layoutLines: 'supported',
    nextLine: 'supported',
    layoutWithLineWidths: 'single-width',
    rangeRects: APPLE_GEOMETRY_ACCURACY,
    rangeAnnotationsAt: 'supported',
    hitTest: APPLE_GEOMETRY_ACCURACY,
  },
} as const satisfies TextGeometryBackendCapabilities;

function hostCallBridge(): AppleHostCall | null {
  const hostCall = (
    globalThis as typeof globalThis & {
      __hostCall?: AppleHostCall;
    }
  ).__hostCall;

  return typeof hostCall === 'function' ? hostCall : null;
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function readLineCursor(cursor: LineCursor | null): ApplePreparedCursor {
  if (cursor === null) {
    return {
      [appleTextLineCursorBrand]: true,
      lineIndex: 0,
    };
  }

  return cursor as unknown as ApplePreparedCursor;
}

function createCursor(lineIndex: number): LineCursor {
  return {
    [appleTextLineCursorBrand]: true,
    lineIndex,
  } as unknown as LineCursor;
}

function sanitizeWidth(value: number | undefined): number {
  return isFiniteNumber(value) && value > 0 ? value : 1;
}

function normalizeFontWeight(value: ParagraphFontWeight | undefined): number {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(100, Math.min(900, Math.round(value)));
  }

  switch (value) {
  case 'bold':
    return 700;
  case '100':
    return 100;
  case '200':
    return 200;
  case '300':
    return 300;
  case '500':
    return 500;
  case '600':
    return 600;
  case '700':
    return 700;
  case '800':
    return 800;
  case '900':
    return 900;
  case '400':
  case 'normal':
  case undefined:
    return DEFAULT_FONT_WEIGHT;
  default:
    return DEFAULT_FONT_WEIGHT;
  }
}

function splitFontFamilies(value: string): readonly string[] {
  const families: string[] = [];
  let current = '';
  let quote: '"' | "'" | null = null;

  for (const character of value) {
    if (quote !== null) {
      if (character === quote) {
        quote = null;
        continue;
      }
      current += character;
      continue;
    }

    if (character === '"' || character === "'") {
      quote = character;
      continue;
    }

    if (character === ',') {
      const trimmed = current.trim();
      if (trimmed.length > 0) {
        families.push(trimmed);
      }
      current = '';
      continue;
    }

    current += character;
  }

  const trimmed = current.trim();
  if (trimmed.length > 0) {
    families.push(trimmed);
  }

  return families;
}

function normalizeFontFamilies(value: ParagraphTextStyle['fontFamily']): readonly string[] {
  if (Array.isArray(value)) {
    return value
      .flatMap((entry) => splitFontFamilies(entry))
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0);
  }

  if (typeof value === 'string') {
    return splitFontFamilies(value)
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0);
  }

  return [];
}

function normalizeTextStyle(style: ParagraphTextStyle | undefined, paragraphLocale: string | undefined): AppleHostTextStyle {
  return {
    fontFamilies: normalizeFontFamilies(style?.fontFamily),
    fontSize: isFiniteNumber(style?.fontSize) && style!.fontSize! > 0 ? style!.fontSize! : DEFAULT_FONT_SIZE,
    fontWeight: normalizeFontWeight(style?.fontWeight),
    fontStyle: style?.fontStyle === 'italic' ? 'italic' : DEFAULT_FONT_STYLE,
    fontVariantNumeric:
      typeof style?.fontVariantNumeric === 'string' && style.fontVariantNumeric.trim().length > 0
        ? style.fontVariantNumeric.trim()
        : undefined,
    lineHeight:
      isFiniteNumber(style?.lineHeight) && style!.lineHeight! > 0
        ? style!.lineHeight!
        : undefined,
    letterSpacing: isFiniteNumber(style?.letterSpacing) ? style.letterSpacing : undefined,
    locale:
      typeof style?.locale === 'string' && style.locale.trim().length > 0
        ? style.locale.trim()
        : paragraphLocale,
  };
}

function styleKey(style: AppleHostTextStyle): string {
  return JSON.stringify(style);
}

function pushHostTextSpan(
  spans: AppleHostTextSpan[],
  text: string,
  style: AppleHostTextStyle,
): void {
  if (text.length === 0) {
    return;
  }

  const previous = spans[spans.length - 1];
  if (previous && styleKey(previous.style) === styleKey(style)) {
    previous.text += text;
    return;
  }

  spans.push({
    text,
    style,
  });
}

function throwUnsupportedAppleFeature(feature: string): never {
  throw new Error(`@exact/text apple backend does not support ${feature} yet.`);
}

function assertAppleParagraphSpecSupported(spec: ParagraphSpec): void {
  if (spec.spans.some((span) => span.type === 'attachment')) {
    throwUnsupportedAppleFeature(
      'attachment spans (canonical offsets require one U+FFFC code unit)',
    );
  }
  if (spec.writingMode !== undefined && spec.writingMode !== 'horizontal-tb') {
    throwUnsupportedAppleFeature(`writingMode="${spec.writingMode}"`);
  }
  if (spec.textAlign !== undefined && spec.textAlign !== 'auto') {
    throwUnsupportedAppleFeature(`textAlign="${spec.textAlign}"`);
  }
  if (spec.lineBreak !== undefined && spec.lineBreak !== 'normal') {
    throwUnsupportedAppleFeature(`lineBreak="${spec.lineBreak}"`);
  }
  if (spec.overflowWrap !== undefined && spec.overflowWrap !== 'normal') {
    throwUnsupportedAppleFeature(`overflowWrap="${spec.overflowWrap}"`);
  }

  for (const span of spec.spans) {
    if (span.type !== 'text' || span.style === undefined) {
      continue;
    }
    const { style } = span;
    if (style.fontFeatureSettings !== undefined) {
      throwUnsupportedAppleFeature('fontFeatureSettings');
    }
    if (style.fontVariationSettings !== undefined) {
      throwUnsupportedAppleFeature('fontVariationSettings');
    }
    if (style.writingMode !== undefined && style.writingMode !== 'horizontal-tb') {
      throwUnsupportedAppleFeature(`span writingMode="${style.writingMode}"`);
    }
    if (style.textAlign !== undefined && style.textAlign !== 'auto') {
      throwUnsupportedAppleFeature(`span textAlign="${style.textAlign}"`);
    }
  }
}

function normalizeParagraphPayload(spec: ParagraphSpec, key: string): AppleHostParagraphPayload {
  const spans: AppleHostTextSpan[] = [];

  for (const span of spec.spans) {
    if (span.type === 'attachment') {
      throwUnsupportedAppleFeature(
        'attachment spans (canonical offsets require one U+FFFC code unit)',
      );
    }

    pushHostTextSpan(
      spans,
      span.text,
      normalizeTextStyle(span.style, spec.locale),
    );
  }

  return {
    key,
    spans,
    baseDirection: spec.baseDirection,
    maxLines: spec.maxLines,
    truncation: spec.truncation,
  };
}

function rangeAnnotationsAt(
  spec: ParagraphSpec,
  position: number,
): readonly ParagraphRangeAnnotation[] {
  const annotations = spec.ranges ?? [];
  if (annotations.length === 0) {
    return [];
  }

  return annotations.filter((annotation) => {
    const { start, end } = annotation.range;
    if (end === start) {
      return position === start;
    }
    return position >= start && position < end;
  });
}

function isValidParagraphMetrics(value: unknown): value is AppleHostParagraphMetrics {
  if (!value || typeof value !== 'object') {
    return false;
  }

  const metrics = value as Record<string, unknown>;
  return isFiniteNumber(metrics.width) &&
    isFiniteNumber(metrics.height) &&
    isFiniteNumber(metrics.lineCount) &&
    typeof metrics.didTruncate === 'boolean';
}

function isValidHostLine(value: unknown): value is AppleHostLine {
  if (!value || typeof value !== 'object') {
    return false;
  }

  const line = value as Record<string, unknown>;
  const origin = line.origin as Record<string, unknown> | undefined;

  return isFiniteNumber(line.index) &&
    isFiniteNumber(line.start) &&
    isFiniteNumber(line.end) &&
    isFiniteNumber(line.width) &&
    isFiniteNumber(line.height) &&
    isFiniteNumber(line.baseline) &&
    !!origin &&
    isFiniteNumber(origin.x) &&
    isFiniteNumber(origin.y);
}

function invokeHostCall<T>(
  hostCall: AppleHostCall,
  operation: string,
  payload: unknown,
): T | null {
  try {
    return (hostCall(operation, JSON.stringify(payload)) as T | null | undefined) ?? null;
  } catch {
    return null;
  }
}

function buildFallbackMetrics(): ParagraphMetrics {
  return {
    geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    width: 0,
    height: 0,
    lineCount: 0,
    didTruncate: false,
  };
}

function intersectRangeRect(line: ParagraphLine, range: TextRange): ParagraphRangeRect | null {
  const start = Math.max(line.textRange.start, range.start);
  const end = Math.min(line.textRange.end, range.end);
  if (end <= start) {
    return null;
  }

  const lineLength = Math.max(1, line.textRange.end - line.textRange.start);
  const startRatio = (start - line.textRange.start) / lineLength;
  const endRatio = (end - line.textRange.start) / lineLength;
  const x = line.origin.x + line.width * startRatio;
  const width = Math.max(0, line.width * (endRatio - startRatio));

  return {
    geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    lineIndex: line.index,
    rect: {
      x,
      y: line.origin.y,
      width,
      height: line.height,
    },
  };
}

function hitTestLines(lines: readonly ParagraphLine[], point: Point): ParagraphHitTestResult | null {
  for (const line of lines) {
    if (point.y < line.origin.y || point.y > line.origin.y + line.height) {
      continue;
    }

    const lineLength = Math.max(1, line.textRange.end - line.textRange.start);
    const clampedRatio = line.width > 0 ? Math.max(0, Math.min(1, (point.x - line.origin.x) / line.width)) : 0;
    const offset = line.textRange.start + Math.round(clampedRatio * lineLength);

    return {
      geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
      offsetUnit: PARAGRAPH_OFFSET_UNIT,
      offset: Math.max(line.textRange.start, Math.min(line.textRange.end, offset)),
      affinity: 'forward',
      isInside:
        point.x >= line.origin.x &&
        point.x <= line.origin.x + line.width,
      activeAnnotations: [],
    };
  }

  return null;
}

function readLayoutLines(
  hostCall: AppleHostCall,
  paragraph: AppleHostParagraphPayload,
  maxWidth: number,
): readonly ParagraphLine[] {
  const response = invokeHostCall<AppleHostLayoutResponse>(
    hostCall,
    'text.layoutParagraph',
    {
      paragraph,
      maxWidth,
    } satisfies AppleHostLayoutRequest,
  );

  if (!response || !Array.isArray(response.lines)) {
    return [];
  }

  return response.lines
    .filter(isValidHostLine)
    .map((line): ParagraphLine => ({
      geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
      offsetUnit: PARAGRAPH_OFFSET_UNIT,
      index: Math.trunc(line.index),
      textRange: {
        start: Math.trunc(line.start),
        end: Math.trunc(line.end),
      },
      width: line.width,
      height: line.height,
      baseline: line.baseline,
      origin: {
        x: line.origin.x,
        y: line.origin.y,
      },
    }));
}

function measureParagraph(
  hostCall: AppleHostCall,
  paragraph: AppleHostParagraphPayload,
  widthMode: AppleHostWidthMode,
  maxWidth?: number,
): ParagraphMetrics {
  const response = invokeHostCall<AppleHostParagraphMetrics>(
    hostCall,
    'text.measureParagraph',
    {
      paragraph,
      widthMode,
      maxWidth,
    } satisfies AppleHostMeasureRequest,
  );

  return isValidParagraphMetrics(response)
    ? {
        ...response,
        geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
        offsetUnit: PARAGRAPH_OFFSET_UNIT,
      }
    : buildFallbackMetrics();
}

export interface AppleTextGeometryBackendOptions {
  readonly hostCall?: AppleHostCall | null;
}

export function isAppleTextGeometryEnvironment(): boolean {
  const globals = globalThis as typeof globalThis & {
    __exactPlatform?: unknown;
  };
  const platform = typeof globals.__exactPlatform === 'string'
    ? globals.__exactPlatform.toLowerCase()
    : null;

  if (platform !== 'ios' && platform !== 'mac' && platform !== 'macos') {
    return false;
  }

  return hostCallBridge() !== null;
}

export function createAppleTextGeometryBackend(
  options: AppleTextGeometryBackendOptions = {},
): SyncTextGeometryBackend {
  const hostCall = options.hostCall ?? hostCallBridge();
  if (hostCall === null) {
    throw new Error('Apple text geometry requires the native __hostCall bridge.');
  }

  const cache = new BoundedLruMap<string, PreparedParagraph>(DEFAULT_PARAGRAPH_CACHE_LIMIT);

  return {
    capabilities: appleTextGeometryCapabilities,
    geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    prepare(spec: ParagraphSpec): PreparedParagraph {
      assertAppleParagraphSpecSupported(spec);
      const key = createParagraphKey(spec);
      const fullSpecKey = createFullParagraphKey(spec, key);
      const cached = cache.get(fullSpecKey);
      if (cached) {
        return cached;
      }

      const hostParagraph = normalizeParagraphPayload(spec, key);
      const measureCache = new Map<string, ParagraphMetrics>();
      const lineCache = new Map<number, readonly ParagraphLine[]>();
      let minContentWidthCache: number | null = null;
      let maxContentWidthCache: number | null = null;

      const paragraph: PreparedParagraph = {
        capabilities: appleTextGeometryCapabilities,
        geometryAccuracy: APPLE_GEOMETRY_ACCURACY,
        offsetUnit: PARAGRAPH_OFFSET_UNIT,
        handle: { key } as unknown as PreparedParagraph['handle'],
        spec,
        measure(options: ParagraphMeasureOptions): ParagraphMetrics {
          const width = sanitizeWidth(options.maxWidth);
          const cacheKey = `measure:${width}`;
          const cachedMetrics = measureCache.get(cacheKey);
          if (cachedMetrics) {
            return cachedMetrics;
          }

          const metrics = measureParagraph(hostCall, hostParagraph, 'definite', width);
          measureCache.set(cacheKey, metrics);
          return metrics;
        },
        minContentWidth(): number {
          if (minContentWidthCache !== null) {
            return minContentWidthCache;
          }

          minContentWidthCache = Math.max(
            DEFAULT_MIN_CONTENT_WIDTH,
            measureParagraph(hostCall, hostParagraph, 'min-content').width,
          );
          return minContentWidthCache;
        },
        maxContentWidth(): number {
          if (maxContentWidthCache !== null) {
            return maxContentWidthCache;
          }

          maxContentWidthCache = Math.max(
            DEFAULT_MIN_CONTENT_WIDTH,
            measureParagraph(hostCall, hostParagraph, 'max-content').width,
          );
          return maxContentWidthCache;
        },
        layoutLines(options) {
          const width = sanitizeWidth(options.maxWidth);
          const cachedLines = lineCache.get(width);
          if (cachedLines) {
            return cachedLines;
          }

          const lines = readLayoutLines(hostCall, hostParagraph, width);
          lineCache.set(width, lines);
          return lines;
        },
        nextLine(cursor, options): ParagraphLineStep | null {
          const lines = this.layoutLines(options);
          const nextIndex = readLineCursor(cursor).lineIndex;
          const line = lines[nextIndex];
          if (!line) {
            return null;
          }

          return {
            line,
            cursor: createCursor(nextIndex + 1),
          };
        },
        layoutWithLineWidths(getWidthForLineY: ParagraphLineWidthResolver): readonly ParagraphLine[] {
          return this.layoutLines({ maxWidth: sanitizeWidth(getWidthForLineY(0)) });
        },
        rangeRects(range: TextRange, options): readonly ParagraphRangeRect[] {
          if (range.end <= range.start) {
            return [];
          }

          const lines = this.layoutLines(options);
          return lines
            .map((line) => intersectRangeRect(line, range))
            .filter((rect): rect is ParagraphRangeRect => rect !== null);
        },
        rangeAnnotationsAt(position): readonly ParagraphRangeAnnotation[] {
          return rangeAnnotationsAt(spec, position);
        },
        hitTest(point: Point, options): ParagraphHitTestResult | null {
          const result = hitTestLines(this.layoutLines(options), point);
          if (result === null) {
            return null;
          }

          return {
            ...result,
            activeAnnotations: rangeAnnotationsAt(spec, result.offset),
          };
        },
      };

      cache.set(fullSpecKey, paragraph);
      return paragraph;
    },
    clearCache(): void {
      cache.clear();
    },
  };
}
